argv:
$r='E:\pc-github-relay'; 
Write-Output 'BEFORE'; git -C $r status --porcelain=v2 -b;
if((Test-Path "$r\.git\rebase-merge") -or (Test-Path "$r\.git\rebase-apply")){
  Write-Output 'ABORTING_REBASE'; git -C $r rebase --abort; if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
}else{Write-Output 'NO_REBASE_STATE'}
Write-Output 'AFTER_ABORT'; git -C $r status --porcelain=v2 -b;
$dirty=(git -C $r status --porcelain);
if($dirty){Write-Output 'DIRTY_WORKTREE_STOP'; $dirty; exit 3}
git -C $r fetch origin; if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
git -C $r pull --rebase origin agent/pc-github-relay; if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
Write-Output 'RECOVERED'; git -C $r status --porcelain=v2 -b; git -C $r rev-parse HEAD; git -C $r rev-list --left-right --count HEAD...origin/agent/pc-github-relay
